-- Get owner badges update R set R.OwnerCounts = coalesce( ( select ResponsibilityTypeName as ResponsibilityType, ResponsibilityTypeID, '[' + string_Agg(ResourceID, ',') + ']' as UsersList, count(1) as [Count], 0 as Expanded from ( select ResponsibilityTypeName, ResponsibilityTypeID, ResourceID from ResponsibilityDetail where ( AssetID = R.AssetID OR (AssetID = 0 and AssetTypeID = R.AssetTypeID) ) and IsVisible = 1 group by ResponsibilityTypeName, ResponsibilityTypeID, ResourceID ) O group by ResponsibilityTypeName, ResponsibilityTypeID for json path ), '[]' ) from #nodes R inner join #hopAssets H on H.[Key] = R.[Key] and H.HopNumber = @hopNumber where R.Parsed = 0;
update R set R.OwnerCounts = '[]', R.IsLeaf = 0 from #nodes R inner join #hopAssets H on H.[Key] = R.[Key] and H.HopNumber = @hopNumber where R.IsLeaf is null and R.Parsed = 0; end
